-- sql
WITH base AS (SELECT toStartOfWeek(toDateTime64(analytics.orders.created_at, 9, 'UTC')) AS `period`, analytics.orders.status AS `status`, SUM(analytics.orders.amount_cents) AS `revenue`, COUNT(analytics.orders.status) AS `orders` FROM analytics.orders WHERE analytics.orders.tenant_id = ? GROUP BY `period`, `status`) SELECT `period`, `status`, (toFloat64(`revenue`) / NULLIF(`orders`, 0)) AS `monthlyAov` FROM base ORDER BY `period` LIMIT 5
